var i=53;var a=[{id:`cooking-053-01`,theoryId:53,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What is required for ordinary starch gelatinization?`,ua:`Що потрібно для звичайної клейстеризації крохмалю?`},explanation:{en:`Hydrated granules absorb water and swell during heating.`,ua:`Зволожені крохмальні гранули поглинають воду й набухають під час нагрівання.`},options:[{id:`a`,text:{en:`Enough available water plus heating`,ua:`Достатньо доступної води та нагрівання`}},{id:`b`,text:{en:`Only freezing dry starch`,ua:`Лише заморожування сухого крохмалю`}},{id:`c`,text:{en:`No water and no heat`,ua:`Без води та нагрівання`}}],answer:{optionIds:[`a`]}},{id:`cooking-053-02`,theoryId:53,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Retrogradation involves starch molecules reassociating as cooked starch cools.`,ua:`Ретроградація — це повторне зближення молекул крохмалю під час охолодження приготованої маси.`},explanation:{en:`Reassociation firms starch-rich foods and contributes to staling.`,ua:`Повторне зближення ущільнює крохмалисті продукти й сприяє черствінню.`},answer:{value:!0}},{id:`cooking-053-03`,theoryId:53,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match starch concepts to observations.`,ua:`Поєднайте крохмальні процеси зі спостереженнями.`},explanation:{en:`Timing and moisture determine how starch changes texture.`,ua:`Час і волога визначають, як крохмаль змінює текстуру.`},leftItems:[{id:`l1`,text:{en:`Gelatinization`,ua:`Клейстеризація`}},{id:`l2`,text:{en:`Retrogradation`,ua:`Ретроградація`}},{id:`l3`,text:{en:`Starch slurry`,ua:`Крохмальна суспензія`}}],rightItems:[{id:`r3`,text:{en:`Starch dispersed in cool liquid before thickening`,ua:`Крохмаль розмішаний у холодній рідині до загущення`}},{id:`r2`,text:{en:`Cooled paste becomes firmer`,ua:`Охолоджена крохмальна маса стає щільнішою`}},{id:`r1`,text:{en:`Granules swell in heated water`,ua:`Гранули набухають у нагрітій воді`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-053-04`,theoryId:53,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Order the normal process of thickening sauce with a starch slurry.`,ua:`Упорядкуйте загущення соусу крохмальною суспензією.`},explanation:{en:`Starting with cool liquid helps avoid dry starch clumps.`,ua:`Попереднє розмішування в холодній рідині зменшує грудочки.`},steps:[{id:`s2`,text:{en:`Whisk slurry into warm sauce`,ua:`Вмішати суспензію в теплий соус`}},{id:`s1`,text:{en:`Disperse starch in cool water`,ua:`Розмішати крохмаль у холодній воді`}},{id:`s3`,text:{en:`Heat and stir until thickening develops`,ua:`Нагрівати й перемішувати до загущення`}}],answer:{order:[`s1`,`s2`,`s3`]}},{id:`cooking-053-05`,theoryId:53,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Your cornstarch sauce has powdery lumps. Best preventive technique?`,ua:`У соусі з кукурудзяним крохмалем є порошкові грудочки. Як запобігти їм наступного разу?`},explanation:{en:`Pre-dispersing granules limits clumping before gelatinization.`,ua:`Попереднє розподілення гранул обмежує злипання до клейстеризації.`},options:[{id:`a`,text:{en:`Add dry starch straight into boiling sauce in a pile`,ua:`Насипати сухий крохмаль купою прямо в киплячий соус`}},{id:`b`,text:{en:`Make a smooth cold-liquid slurry first`,ua:`Спочатку зробити однорідну суспензію в холодній рідині`}},{id:`c`,text:{en:`Stop stirring entirely`,ua:`Повністю припинити перемішування`}}],answer:{optionIds:[`b`]}},{id:`cooking-053-06`,theoryId:53,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which factors can influence starch paste thickness?`,ua:`Які чинники можуть впливати на густоту крохмальної маси?`},explanation:{en:`Different starches and cooking conditions produce different gel and paste properties.`,ua:`Різні крохмалі й умови приготування формують різну структуру та густоту.`},options:[{id:`a`,text:{en:`Water available for swelling`,ua:`Доступна для набухання вода`}},{id:`b`,text:{en:`Heating and stirring history`,ua:`Історія нагрівання та перемішування`}},{id:`c`,text:{en:`Starch botanical source`,ua:`Ботанічне походження крохмалю`}},{id:`d`,text:{en:`Color of the cooking apron`,ua:`Колір кухарського фартуха`}}],answer:{optionIds:[`a`,`b`,`c`]}}];var n={theoryId:53,exercises:a};export{n as default,a as exercises,i as theoryId};